Contract GenerateLoanLetterAndAgreementModule::genereateApprovalLetter(id:Integer): Boolean {

            precondition:
          loanRequest:LoanRequest = LoanRequest.allInstance()->any(o | o.RequestID = id)

            postcondition:
          let approvalLetter:ApprovalLetter in approvalLetter.oclIsNew() and approvalLetter.Content = "ApprovalLetterContent" and LoanRequest.allInstance()->includes(loanRequest) and loanRequest.AttachedApprovalLetter = approvalLetter and CurrentLoanRequest = loanRequest and result = true

        }
